fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    let mut max_value = v[0];
    let mut max_index = 0;

    for i in 0..=end {
        if v[i] > max_value {
            max_value = v[i];
            max_index = i;
        }
    }

    (max_value, max_index)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    let mut min_value = v[start];
    let mut min_index = start;

    for i in start..v.len() {
        if v[i] < min_value {
            min_value = v[i];
            min_index = i;
        }
    }

    (min_value, min_index)
}

fn barrier(v: &[i32], p: usize) -> bool {
    if p == v.len() - 1 {
        return true; // Vacuously true if p is the last index
    }

    let (max_prefix, _) = find_max_in_prefix(v, p);
    let (min_suffix, _) = find_min_in_suffix(v, p + 1);

    max_prefix < min_suffix
}

fn main() {
    // Example usage
    let arr = [1, 2, 3, 4, 5];
    let index = 2;
    let result = barrier(&arr, index);
    println!("Is index {} a strict partition barrier? {}", index, result);
}